const items = $input.all();

return items.map((item) => {
  const body = item.json.body ?? {};
  const errors = [];

  const callId = String(body.call_id ?? "").trim();
  const leadId = String(body.lead_id ?? "").trim();
  const company = String(body.company ?? "").trim();
  const contactName = String(body.contact_name ?? "").trim();
  const email = String(body.email ?? "").trim();
  const summary = String(body.summary ?? "").trim();
  const nextAction = String(body.next_action ?? "").trim();

  const interestLevel = String(body.interest_level ?? "").trim();
  const leadScore = body.lead_score;
  const followUpRequired = body.follow_up_required;

  if (!callId) errors.push("Missing call_id");
  if (!leadId) errors.push("Missing lead_id");
  if (!company) errors.push("Missing company");
  if (!contactName) errors.push("Missing contact_name");

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.push("Invalid or missing email");
  }

  if (!summary) errors.push("Missing summary");
  if (!nextAction) errors.push("Missing next_action");

  if (!["high", "medium", "low", "none"].includes(interestLevel)) {
    errors.push("Invalid interest_level");
  }

  if (!Number.isInteger(leadScore) || leadScore < 0 || leadScore > 100) {
    errors.push("Invalid lead_score");
  }

  if (typeof followUpRequired !== "boolean") {
    errors.push("Invalid follow_up_required");
  }

  if (errors.length > 0) {
    return {
      json: {
        call_id: callId || null,
        lead_id: leadId || null,
        validation_status: "invalid",
        errors
      }
    };
  }

  return {
    json: {
      call_id: callId,
      lead_id: leadId,
      company,
      contact_name: contactName,
      email,
      interest_level: interestLevel,
      lead_score: leadScore,
      summary,
      next_action: nextAction,
      follow_up_required: followUpRequired,
      validation_status: "valid",
      received_at: new Date().toISOString()
    }
  };
});

