const items = $input.all();

return items.map((item) => {
  // Extract the text generated by Gemini.
  const parts = item.json.content?.parts ?? [];

  const rawText = parts
    .map((part) => part.text ?? "")
    .join("\n")
    .trim();

  if (!rawText) {
    throw new Error("Gemini returned an empty email draft");
  }

  // Remove optional Markdown code fences.
  const cleanedText = rawText
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  let draft;

  try {
    draft = JSON.parse(cleanedText);
  } catch (error) {
    throw new Error(
      `Invalid JSON returned by Gemini: ${error.message}`
    );
  }

  if (
    !draft ||
    typeof draft !== "object" ||
    Array.isArray(draft)
  ) {
    throw new Error("Email draft must be a JSON object");
  }

  if (
    typeof draft.subject !== "string" ||
    !draft.subject.trim()
  ) {
    throw new Error("Missing or invalid email subject");
  }

  if (
    typeof draft.body !== "string" ||
    !draft.body.trim()
  ) {
    throw new Error("Missing or invalid email body");
  }

  // Retrieve the original validated request.
  const original = $("Validate Follow-Up Data").first().json;

  return {
    json: {
      call_id: original.call_id,
      lead_id: original.lead_id,
      company: original.company,
      contact_name: original.contact_name,
      email: original.email,
      interest_level: original.interest_level,
      lead_score: original.lead_score,
      subject: draft.subject.trim(),
      body: draft.body.trim(),
      follow_up_required: true,
      draft_status: "draft",
      generated_at: new Date().toISOString(),
      model_provider: "google_gemini"
    }
  };
});

